"""Confirm that a plaintext (non-TLS) connection never speaks the Redis protocol."""
import socket
import sys

def probe(port):
    s = socket.create_connection(("127.0.0.1", port), timeout=5)
    s.settimeout(5)
    try:
        s.sendall(b"PING\r\n")
        try:
            data = s.recv(256)
        except (socket.timeout, ConnectionResetError) as e:
            return f"port {port}: no RESP reply ({type(e).__name__}) -> OK"
        if data == b"":
            return f"port {port}: connection closed with no data -> OK"
        if data.startswith(b"+") or data.startswith(b"-") or data.startswith(b"$"):
            return f"port {port}: SPOKE RESP: {data[:60]!r} -> FAIL"
        return f"port {port}: non-RESP bytes {data[:32]!r} -> OK (TLS alert/garbage)"
    finally:
        s.close()

if __name__ == "__main__":
    bad = False
    for port in (6379, 6380):
        try:
            result = probe(port)
        except Exception as e:  # connection refused would also be a pass for plaintext
            result = f"port {port}: {type(e).__name__}: {e} -> OK"
        print(result)
        if result.endswith("FAIL"):
            bad = True
    sys.exit(1 if bad else 0)

